		setAgentDir(dir);
		await ensureRuntimeTools(dir);
		const rgBefore = statSync(join(dir, "bin", "rg")).size;
		await ensureRuntimeTools(dir);
		expect(statSync(join(dir, "bin", "rg")).size).toBe(rgBefore);
	});

